#!/usr/bin/env node
/**
 * Regenerates db/neon/0001_baseline.sql from Supabase's live catalog (issue #136).
 *
 *   SOURCE_DATABASE_URL=<Supabase> node scripts/neon/generate-baseline.mjs
 *
 * Read-only on the source. Run it right before cutover, so any migration that
 * reached production after the last run is in the Neon schema too -- the copy
 * refuses to run if the source has a column the target lacks.
 *
 * What it writes, and what it deliberately leaves out, is described in the
 * header of the generated file.
 */

import { writeFileSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import pg from 'pg'

const out = join(dirname(fileURLToPath(import.meta.url)), '..', '..', 'db', 'neon', '0001_baseline.sql')
const client = new pg.Client({ connectionString: process.env.SOURCE_DATABASE_URL, ssl: { rejectUnauthorized: false } })
await client.connect()
const q = async sql => (await client.query(sql)).rows

// Foreign keys into Supabase's auth.users point at public.users instead: under
// Supabase the two shared ids, and on Neon public.users is the login's user.
const repoint = def => def.replace(/REFERENCES auth\.users\(id\)/g, 'REFERENCES public.users(id)')
// Qualify bare table references, so the file does not depend on search_path.
const qualify = def => def.replace(/REFERENCES (?!public\.)(\w+)\(/g, 'REFERENCES public.$1(')

const tables = await q(`
  select c.oid, c.relname
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind = 'r'
   order by c.relname`)

const blocks = []
for (const t of tables) {
  const cols = await q(`
    select '  ' || quote_ident(a.attname) || ' ' || format_type(a.atttypid, a.atttypmod)
           || case when a.attnotnull then ' not null' else '' end
           || coalesce(' default ' || pg_get_expr(d.adbin, d.adrelid), '') as line
      from pg_attribute a
      left join pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
     where a.attrelid = ${t.oid} and a.attnum > 0 and not a.attisdropped
     order by a.attnum`)
  const cons = await q(`
    select '  constraint ' || quote_ident(conname) || ' ' || pg_get_constraintdef(oid) as line
      from pg_constraint
     where conrelid = ${t.oid} and contype in ('p', 'u', 'c')
     order by case contype when 'u' then 0 when 'p' then 1 else 2 end, conname`)
  blocks.push(`create table public.${t.relname} (\n${[...cols, ...cons].map(r => r.line).join(',\n')}\n);`)
}

const fks = await q(`
  select 'alter table public.' || quote_ident(c.relname) || ' add constraint ' || quote_ident(con.conname) || ' '
         || pg_get_constraintdef(con.oid) || ';' as line,
         con.confrelid = 'auth.users'::regclass as from_auth
    from pg_constraint con
    join pg_class c on c.oid = con.conrelid
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and con.contype = 'f'
   order by c.relname, con.conname`)

const indexes = await q(`
  select indexdef || ';' as line
    from pg_indexes i
   where schemaname = 'public'
     and not exists (select 1 from pg_constraint con where con.conname = i.indexname)
   order by tablename, indexname`)

const header = `-- Chambers on Neon: baseline schema (issue #136).
--
-- GENERATED by scripts/neon/generate-baseline.mjs from the live Supabase catalog
-- on ${new Date().toISOString().slice(0, 10)}. Do not edit by hand; regenerate instead.
--
-- It is the production \`public\` schema as it stands, not a replay of
-- supabase/migrations, which also carries Supabase-only pieces. What is
-- deliberately different from Supabase:
--
--   * Foreign keys that pointed at Supabase's auth.users point at public.users.
--     Every one of those ids was already a public.users id, because the
--     on_auth_user_created trigger created the row with the same id.
--   * No row-level security policies, helper functions (is_admin, my_body_ids,
--     ...), or the on_auth_user_created trigger. They all asked Supabase Auth who
--     the caller was, which does not exist here. Every route already enforces
--     access in application code before it queries.
--   * RLS is still ENABLED on every table, with no policies. Only the table owner
--     and roles given a policy (chambers_server, in 0003) see rows. Default deny.
--   * revoke_user_sessions() is gone: sessions are rows in auth_sessions (0002).
--   * Column comments are not carried over; they remain in supabase/migrations.
--
-- Apply 0001-0003 to an empty Neon database, then scripts/neon/copy-data.mjs --
-- or run scripts/neon/cutover.mjs, which does both.

create extension if not exists pgcrypto;
`

const sql = [
  header,
  blocks.join('\n\n'),
  '',
  '-- Foreign keys. Those marked (auth) referenced auth.users on Supabase.',
  ...fks.map(f => qualify(repoint(f.line)) + (f.from_auth ? ' -- (auth)' : '')),
  '',
  '-- Indexes beyond those that back primary keys and unique constraints.',
  ...indexes.map(i => i.line),
  '',
  '-- Default deny for every role but the owner. See the header.',
  `do $$
declare t record;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;`,
  '',
].join('\n')

writeFileSync(out, sql)
console.log(`Wrote ${out}: ${tables.length} tables, ${fks.length} foreign keys (${fks.filter(f => f.from_auth).length} from auth.users), ${indexes.length} indexes.`)
await client.end()
